$j('#her2Status').change(
function () {
var value = getValue('her2Status.value');
if (value == 664) {
// $j('#er_pr_her').val('Negative (0 1+)');
setValue('er_pr_her.value', 'Negative (0 1+)');
}
else if (value == 8710) {
// $j('#er_pr_her').text('Equivocal (2+)');
setValue('er_pr_her.value', 'Equivocal (2+)');

}
else if (value == 530427){
setValue('er_pr_her.value', 'Positive (3+)');

// $j('#er_pr_her').text('Positive (3+)');
}
});
